#include <bits/stdc++.h>
using namespace std;
using int64 = long long;
const int MOD = 1e9 + 7;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<int64> h(N);
    for (int i = 0; i < N; i++) cin >> h[i];

    int64 ans = 1;

    // For each column pair, we need to check compatibility
    for (int i = 0; i + 1 < N; i++) {
        int64 h1 = h[i], h2 = h[i + 1];
        if (h1 == 1 && h2 == 1) {
            // single cell each: condition applies to no 2x2 block, so any color works
            ans = (ans * 2) % MOD;
        } else if (h1 == 1 || h2 == 1) {
            // one column height 1: condition involves at most 1 row => always possible
            ans = (ans * 2) % MOD;
        } else {
            // Both >= 2: the pattern is forced and must match
            // The condition forces that row parity patterns alternate.
            // If heights differ by more than 1, impossible
            if (abs(h1 - h2) > 1) {
                ans = 0;
                break;
            }
            // If equal heights, exactly 2 ways (choose first cell of next column)
            // If differ by 1, exactly 1 way (no choice)
            if (h1 == h2) {
                ans = (ans * 2) % MOD;
            }
            // else heights differ by 1: multiply by 1 (no change)
        }
    }

    // Multiply by 2^{h[0]} for the first column choices
    int64 firstColWays = 1;
    for (int64 i = 0; i < h[0]; i++) {
        firstColWays = (firstColWays * 2) % MOD;
    }
    ans = (ans * firstColWays) % MOD;

    cout << ans << "\n";
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    vector<long long> h(N);
    for (int i = 0; i < N; ++i) cin >> h[i];

    // We process columns from left to right.
    // For a pair of adjacent columns, on rows 1..min(h[i], h[i+1]),
    // the condition on every 2x2 block implies:
    //   (color[i][j] xor color[i+1][j]) is constant over j
    // equivalently, the next column is either equal to the previous one
    // on the overlap, or its bitwise complement on the overlap.
    //
    // Therefore, while sweeping, the only relevant information is:
    // for the current column, among its h_i cells, how many assignments
    // are possible. Because all constraints only relate overlapping prefixes,
    // the count depends only on whether the current column height grew or shrank.
    //
    // Let dp = number of valid colorings up to current column.
    // Initially, first column can be arbitrary: 2^{h1}.
    //
    // Transition from height a to b:
    // Let m = min(a,b).
    // For any coloring of current column:
    //   - choose whether next column matches or complements on first m cells: 2 choices
    //   - remaining max(0, b-a) cells (if b>a) are free
    // Hence each current coloring extends in exactly:
    //   2 * 2^{max(0,b-a)} ways
    // = 2^{1 + max(0,b-a)} ways.
    //
    // Thus total:
    //   answer = 2^{h1} * product_{i=1}^{N-1} 2^{1 + max(0, h_{i+1}-h_i)}
    //          = 2^{ h1 + (N-1) + sum max(0,h_{i+1}-h_i) }.
    //
    // This exponent simplifies to:
    //   sum_{i=1}^{N} max(0, h_i - h_{i-1}) + (N-1), with h_0=0
    // but direct computation is easy.

    long long exp = h[0];
    for (int i = 0; i + 1 < N; ++i) {
        exp += 1;
        if (h[i + 1] > h[i]) exp += h[i + 1] - h[i];
    }

    auto modpow = [&](long long a, long long e) {
        long long r = 1 % MOD;
        while (e > 0) {
            if (e & 1) r = r * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return r;
    };

    cout << modpow(2, exp) << '\n';
    return 0;
}

import java.util.Scanner;

public class Main {
    static final int MOD = 1_000_000_007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int[] h = new int[N];
        for (int i = 0; i < N; i++) {
            h[i] = sc.nextInt();
        }

        long ans = 1;
        for (int i = 0; i < N - 1; i++) {
            int minH = Math.min(h[i], h[i+1]);
            int maxH = Math.max(h[i], h[i+1]);

            // For the overlapping part, pattern is forced.
            // The extra rows in the taller column can be anything (2 choices per row)
            long extra = 1;
            for (int j = 0; j < maxH - minH; j++) {
                extra = (extra * 2) % MOD;
            }
            ans = (ans * extra) % MOD;
        }

        // For the very first column, all rows can be anything (2^h[0])
        long firstCol = 1;
        for (int j = 0; j < h[0]; j++) {
            firstCol = (firstCol * 2) % MOD;
        }
        ans = (ans * firstCol) % MOD;

        System.out.println(ans);
    }
}

