public class Main {
    static final long MOD = 1_000_000_007;
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        int[] h = new int[N];
        StringTokenizer st = new StringTokenizer(br.readLine());
        for (int i = 0; i < N; i++) h[i] = Integer.parseInt(st.nextToken());

        long ans = 2; // first column: 2 choices (all determined by first cell + diff sequence, but diff sequence is free)
        // Actually first column has h[0] squares, 2^h[0] colorings
        ans = pow(2, h[0]);
        for (int i = 1; i < N; i++) {
            int m = Math.min(h[i-1], h[i]) - 1;
            if (m < 0) { ans = ans * pow(2, h[i]) % MOD; continue; }
            // overlap of m+1 rows, m difference bits must match
            // extra rows in h[i] beyond overlap: h[i] - (m+1) free bits
            long extra = h[i] - (m + 1);
            ans = ans * pow(2, extra) % MOD;
        }
        System.out.println(ans);
    }
    static long pow(long base, long exp) {
        long result = 1; base %= MOD;
        for (; exp > 0; exp >>= 1) { if ((exp&1)==1) result = result*base%MOD; base = base*base%MOD; }
        return result;
    }
}

