public class Main {
    static final long MOD = 1_000_000_007L;

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        int N = fs.nextInt();
        long[] h = new long[N];
        for (int i = 0; i < N; i++) h[i] = fs.nextLong();

        if (N == 1) {
            // Any coloring of h1 cells is valid.
            System.out.println(modPow(2, h[0], MOD));
            return;
        }

        long ans = 1;
        int i = 0;
        while (i < N - 1) {
            long m = Math.min(h[i], h[i + 1]);
            int j = i;
            while (j + 1 < N - 1 && Math.min(h[j + 1], h[j + 2]) == m) j++;

            int len = j - i + 1; // number of adjacent pairs in this block
            long ways = blockWays(len, m);
            ans = ans * ways % MOD;

            i = j + 1;
        }

        System.out.println(ans % MOD);
    }

    // For a maximal block of adjacent pairs all having the same min-height m,
    // and block length len (number of adjacent pairs), compute number of valid colorings.
    static long blockWays(int len, long m) {
        if (m == 0) return 1;

        // Number of columns in the block is len+1.
        // For the first m rows, each row-pattern across columns must satisfy:
        // adjacent columns equal on odd/even row pairs and differ between the two rows.
        //
        // This implies:
        // - If m is even: choose row 1 arbitrarily on all columns => 2^(len+1), then all fixed.
        // - If m is odd : top row additionally free on all columns => 2^(len+1), and row1 free => 2^(len+1)
        //                 but compatibility through adjacent pairs forces each row pattern to be constant
        //                 on connected block under equal-min constraints. Net result below from transfer:
        //
        // More directly, for a block:
        // each column contributes free cells above m independently.
        // constrained first m cells across block produce:
        //   2^(len+1) if m even
        //   2^(len+2) if m odd
        //
        // Let's derive carefully:
        // For rows 1..m in the block's columns:
        // pick colors of row 1 in all len+1 columns: 2^(len+1)
        // for each next row, color in each column is forced to be same as row-1 if transition type '='
        // or opposite if transition type '!='.
        // The 2x2 condition forces transitions to alternate between '=' and '!=' across rows.
        // Therefore exactly one global sequence of transitions once first transition chosen,
        // and first transition must be '!='. So all rows are forced after row 1.
        // Hence constrained part contributes exactly 2^(len+1), regardless of m>=1.
        //
        // Cells above height m in columns taller than m are handled in other blocks / unconstrained tails.
        //
        // However, when moving between blocks, shared columns' cells in lower constrained region
        // are already counted exactly once by the partition into maximal equal-min blocks.
        return modPow(2, len + 1L, MOD);
    }

    static long modPow(long a, long e, long mod) {
        long r = 1 % mod;
        a %= mod;
        while (e > 0) {
            if ((e & 1) == 1) r = r * a % mod;
            a = a * a % mod;
            e >>= 1;
        }
        return r;
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) nextLong();
        }
    }
}

