#define MOD 1000000007LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1;
    while (e > 0) {
        if (e & 1) r = (r * a) % MOD;
        a = (a * a) % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    ll *h = (ll *)malloc((size_t)N * sizeof(ll));
    for (int i = 0; i < N; i++) scanf("%lld", &h[i]);

    if (N == 1) {
        /* Any square can be colored independently */
        printf("%lld\n", mod_pow(2, h[0]));
        free(h);
        return 0;
    }

    /* Let d_i = h_{i+1} - h_i.
       Validity requires |d_i - d_{i-1}| <= 1 for all internal i,
       where d_0 and d_{N-1} are not needed directly.
       More structurally:
       For overlap lengths m_i = min(h_i, h_{i+1}) - 1,
       each adjacent pair of columns must form one of:
         same pattern, complement pattern, or alternating/checker.
       This leads to a simple characterization:
       the answer is 0 unless all consecutive height differences
       change by at most 1.
       If valid, each "mountain/valley segment" contributes one free bit,
       and each positive extra height above the overlap contributes free bits.

       A compact equivalent formula:
       ans = 2^( h1 + sum_{i=2..N} max(0, h_i - h_{i-1} + 1? no ) )
       is NOT correct in general.

       The correct count can be derived by DP on edge types, but because
       each edge only depends on delta = h_{i+1}-h_i and transitions are tiny,
       we can do 4-state DP.

       State for each column i:
       color pair of top two cells pattern class at the bottom overlap frontier.
       Using the 2x2 condition, all columns on overlapping part must be either:
         A: constant 0
         B: constant 1
         C: parity j
         D: parity j^1
       For a pair of adjacent columns with delta = h_{i+1}-h_i:
         if delta == 0: next class can be same or complement (2 options)
         if delta == 1: next class must be one of the two checker classes from constant,
                        or one of the two constant classes from checker (1 option each)
         if delta == -1: symmetric
         if |delta| >= 2: impossible
       Also extra cells above overlap are unconstrained, giving factor 2^(extra).

       More generally, for delta:
         overlap length is min(h_i,h_{i+1}).
         To extend a valid column pattern from one edge to another, the class at height j
         changes with vertical shift parity. This yields the transition:
           possible iff |delta| <= 1,
           and the next class is determined up to complement depending on parity.

       Since only 4 affine patterns exist on a column: x_j = a xor (b&(j&1)).
       Adjacent condition implies (a,b)->(c,d) valid iff for all j:
         x_j + x_{j+1} + y_j + y_{j+1} = 2
       which reduces to:
         if b=d=0 then a^c=1
         if b=d=1 then always valid
         if b!=d then impossible
       after aligning same j. With different heights, truncation allows endpoint freedom.

       A simpler and correct global characterization:
       For each maximal interval where heights are >= t, row t induces a binary string
       with adjacent cells equal/unequal alternating by row. Each connected row segment
       contributes 1 bit. Total answer = 2^(sum_t comp_t), where comp_t is number of
       connected components among columns with h_i >= t, minus constraints between rows.
       Under the 2x2 rule, each component at row t determines row t+1 on overlap, so
       new freedom appears exactly at local maxima cells.

       Final known formula:
         answer = 2^( h_1 + sum_{i=2}^N max(0, h_i - h_{i-1}) )
                * [all internal local minima/maxima satisfy slope change by at most 1]
       which simplifies to 2^(sum positive rises from left, plus h1),
       provided |h_i - h_{i-1}| <= 1 for all i? Let's verify.
       Counterexample [2,2]: formula gives 2^2, but actual is 6? Let's compute:
         two columns height2, 2x2 must have two red two blue => 6. So formula false.

       Let's do exact DP with column classes.
       A column of height h is any binary sequence length h.
       Constraint between adjacent columns only involves first min(h_i,h_{i+1}) cells and
       requires x_j xor x_{j+1} == !(y_j xor y_{j+1}) for all j in overlap-1.
       Thus only the edge-difference sequence matters:
         dx_j = x_j xor x_{j+1}
         dy_j = y_j xor y_{j+1}
         and dx_j xor dy_j = 1.
       Number of columns with given difference sequence is 2 (choice of first cell).
       Therefore choose difference sequences per column so that on each adjacent pair,
       for j < min(h_i,h_{i+1}), dx^i_j xor dx^{i+1}_j = 1.
       This means for each level j, across columns with height >= j+1, the values dx^i_j
       alternate uniquely per connected component, giving 2 choices per component.
       Also each top cell value per connected component of row1 gives 2 choices, but
       row values are linked by differences. Net:
         answer = 2^( C0 + sum_{j>=1} Cj )
       where C0 = number of connected components in columns with h_i>=1,
             Cj = number of connected components in columns with h_i>=j+1.
       Since all h_i>=0 and columns are contiguous, each set is intervals.
       For our single strip 1..N with missing columns where h_i<k, Ck is number of
       segments of columns with h_i>=k+1.
    */

    ll maxh = 0;
    for (int i = 0; i < N; i++) if (h[i] > maxh) maxh = h[i];

    /* Sweep levels using events:
       components at level t among columns with h_i >= t.
       Sum over t=1..maxh of comp(t).
    */
    typedef struct {
        ll h;
        int idx;
    } Event;

    Event *ev = (Event *)malloc((size_t)N * sizeof(Event));
    for (int i = 0; i < N; i++) {
        ev[i].h = h[i];
        ev[i].idx = i;
    }

    int cmp(const void *a, const void *b) {
        ll x = ((const Event *)a)->h;
        ll y = ((const Event *)b)->h;
        if (x < y) return -1;
        if (x > y) return 1;
        return ((const Event *)a)->idx - ((const Event *)b)->idx;
    }
    qsort(ev, (size_t)N, sizeof(Event), cmp);

    char *alive = (char *)calloc((size_t)N, 1);
    ll ansExp = 0;
    ll currComp = 0;
    ll prevH = 0;
    int p = 0;

    while (p < N) {
        ll H = ev[p].h;
        if (H > prevH) {
            ansExp += currComp * (H - prevH);
            prevH = H;
        }

        while (p < N && ev[p].h == H) {
            int i = ev[p].idx;
            alive[i] = 1;
            int left = (i > 0 && alive[i - 1]);
            int right = (i + 1 < N && alive[i + 1]);
            if (!left && !right) currComp += 1;
            else if (left && right) currComp -= 1;
            p++;
        }
    }

    ll ans = mod_pow(2, ansExp % (MOD - 1));
    printf("%lld\n", ans);

    free(alive);
    free(ev);
    free(h);
    return 0;
}
